def status_label(code):
    labels = {200: 'success', 404: 'not found', 500: 'server error'}
    return labels.get(code, 'unknown')

def status_line(code):
    reasons = {200: 'OK', 404: 'Not Found', 500: 'Server Error'}
    if code in reasons:
        return f'HTTP {code} {reasons[code]}'
    return f'HTTP {code}'

